using Microsoft.Playwright;

namespace BARANG.Backoffice.E2ETests;

public sealed class ProductModuleE2ETests : IAsyncLifetime
{
    private const string Company = "42f0e459-6095-45bb-aa13-f38126d91d9c";
    private readonly string baseUrl = Environment.GetEnvironmentVariable("BARANG_E2E_BASE_URL") ?? "http://localhost:5100";
    private IPlaywright playwright = null!; private IBrowser browser = null!; private IBrowserContext context = null!; private IPage page = null!;
    public async ValueTask InitializeAsync(){playwright=await Playwright.CreateAsync();browser=await playwright.Chromium.LaunchAsync(new(){Headless=true,ExecutablePath=Environment.GetEnvironmentVariable("BARANG_E2E_BROWSER_PATH")});context=await browser.NewContextAsync(new(){ViewportSize=new(){Width=1440,Height=1000}});page=await context.NewPageAsync();await Login();}
    public async ValueTask DisposeAsync(){await context.DisposeAsync();await browser.DisposeAsync();playwright.Dispose();}

    [Fact]
    public async Task Products_and_variants_complete_crud_and_locale_surface(){
        string stamp=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds().ToString(); string code="E2E-P"+stamp; string sku="E2E-S"+stamp;
        await Go("en","/manage/products"); await page.GetByRole(AriaRole.Button,new(){Name="Add product",Exact=true}).ClickAsync(); ILocator modal=page.Locator(".barang-modal").Last;
        await modal.Locator("input[name='product-code']").FillAsync(code); await modal.Locator("input[name='product-name']").FillAsync("Browser Product "+stamp);
        await modal.GetByRole(AriaRole.Tab,new(){Name="Product type",Exact=true}).ClickAsync(); await Assertions.Expect(modal.Locator("input[name='product-type']")).ToBeVisibleAsync(); await Assertions.Expect(modal.Locator("input[name='product-uom']")).ToBeVisibleAsync(); foreach(string name in new[]{"product-brand","product-material","product-gender","product-fit","product-style"}) await Assertions.Expect(modal.Locator($"input[name='{name}']")).ToBeVisibleAsync(); await modal.GetByRole(AriaRole.Tab,new(){Name="Details",Exact=true}).ClickAsync();
        await Assertions.Expect(modal.GetByRole(AriaRole.Tab,new(){Name="Product",Exact=true})).ToHaveCountAsync(0);
        string modalWidth=await modal.EvaluateAsync<string>("el=>getComputedStyle(el).width"); Assert.Contains("px",modalWidth);
        bool noHorizontalOverflow=await modal.EvaluateAsync<bool>("el=>el.scrollWidth<=el.clientWidth+1"); Assert.True(noHorizontalOverflow);
        await modal.GetByRole(AriaRole.Button,new(){Name="Save changes",Exact=true}).ClickAsync(); await Assertions.Expect(modal).ToBeHiddenAsync();
        ILocator row=page.Locator(".data-grid tbody tr").Filter(new(){HasText=code}); await Assertions.Expect(row).ToBeVisibleAsync(); await row.GetByRole(AriaRole.Button,new(){Name="Edit",Exact=true}).ClickAsync(); modal=page.Locator(".barang-modal").Last;
        await modal.GetByRole(AriaRole.Tab,new(){Name="Variants / SKU",Exact=true}).ClickAsync(); await Assertions.Expect(modal.GetByRole(AriaRole.Button,new(){Name="Save changes",Exact=true})).ToBeVisibleAsync(); await modal.GetByRole(AriaRole.Tab,new(){Name="Suppliers and product relations",Exact=true}).ClickAsync(); await Assertions.Expect(modal.GetByRole(AriaRole.Button,new(){Name="Add",Exact=true})).ToBeVisibleAsync(); await modal.GetByRole(AriaRole.Tab,new(){Name="Variants / SKU",Exact=true}).ClickAsync(); await modal.GetByRole(AriaRole.Button,new(){Name="Add variant",Exact=true}).ClickAsync(); ILocator variant=page.Locator(".barang-modal").Last;
        await variant.Locator("input[name='variant-sku']").FillAsync(sku); await variant.Locator("input[name='variant-name']").FillAsync("Black Large"); await variant.GetByRole(AriaRole.Button,new(){Name="Save",Exact=false}).ClickAsync(); await Assertions.Expect(page.GetByRole(AriaRole.Dialog,new(){Name="Add variant",Exact=true})).ToBeHiddenAsync(); await Assertions.Expect(modal.Locator("tbody tr").Filter(new(){HasText=sku})).ToBeVisibleAsync();
        foreach(string culture in new[]{"fa","ar","en"}){await Go(culture,"/manage/products");await Assertions.Expect(page.Locator("html")).ToHaveAttributeAsync("dir",culture=="en"?"ltr":"rtl");await page.GetByRole(AriaRole.Button,new(){Name=culture=="fa"?"محصول جدید":culture=="ar"?"منتج جديد":"Add product",Exact=true}).ClickAsync();ILocator editor=page.Locator(".barang-modal").Last;await Assertions.Expect(editor.Locator("input[name='product-code']")).ToBeVisibleAsync();await Assertions.Expect(editor.GetByRole(AriaRole.Tab,new(){Name=culture=="fa"?"گونه‌ها و SKU":culture=="ar"?"المتغيرات وSKU":"Variants / SKU",Exact=true})).ToBeVisibleAsync();await editor.GetByRole(AriaRole.Button,new(){Name=culture=="fa"?"انصراف":culture=="ar"?"إلغاء":"Cancel",Exact=true}).ClickAsync();}
    }
    [Fact]
    public async Task Product_pricing_tab_is_localized_and_is_a_real_sales_price_workspace(){foreach(string culture in new[]{"fa","ar","en"}){await Go(culture,"/manage/products");ILocator row=page.Locator(".data-grid tbody tr").First;await row.GetByRole(AriaRole.Button,new(){Name=culture=="fa"?"مشاهده":culture=="ar"?"عرض":"View",Exact=true}).ClickAsync();ILocator editor=page.Locator(".barang-modal").Last;string tab=culture switch{"fa"=>"قیمت‌گذاری", "ar"=>"التسعير", _=>"Pricing"};await editor.GetByRole(AriaRole.Tab,new(){Name=tab,Exact=true}).ClickAsync();string[] labels=culture switch{"fa"=>new[]{"قیمت‌گذاری","تاریخ شروع","وضعیت","عملیات"},"ar"=>new[]{"التسعير","تاريخ البدء","الحالة","الإجراءات"},_=>new[]{"Pricing","Start date","Status","Actions"}};foreach(string label in labels)await Assertions.Expect(editor).ToContainTextAsync(label);await editor.GetByRole(AriaRole.Button,new(){Name=culture=="fa"?"انصراف":culture=="ar"?"إلغاء":"Cancel",Exact=true}).ClickAsync();}}
    private async Task Login(){await page.GotoAsync($"{baseUrl}/culture?culture=en&returnUrl=%2Flogin",new(){WaitUntil=WaitUntilState.NetworkIdle});await page.Locator("#username").FillAsync(Environment.GetEnvironmentVariable("BARANG_E2E_USERNAME")??"admin");await page.Locator("#password").FillAsync(Environment.GetEnvironmentVariable("BARANG_E2E_PASSWORD")??"BarangDev@2026");await page.Locator("button[type=submit]").ClickAsync();await page.WaitForLoadStateAsync(LoadState.NetworkIdle);if(new Uri(page.Url).AbsolutePath=="/company")await page.Locator($".company-list form:has(input[name=companyId][value='{Company}']) button[type=submit]").ClickAsync();await page.WaitForURLAsync(u=>new Uri(u).AbsolutePath!="/company");}
    private Task Go(string culture,string path)=>page.GotoAsync($"{baseUrl}/culture?culture={culture}&returnUrl={Uri.EscapeDataString(path)}",new(){WaitUntil=WaitUntilState.NetworkIdle});
    private static async Task ChooseFirst(ILocator root,string name){ILocator input=root.Locator($"input[name='{name}']");await Assertions.Expect(input).ToBeEnabledAsync();await input.ClickAsync();ILocator option=input.Locator("..").GetByRole(AriaRole.Option).Nth(1);await Assertions.Expect(option).ToBeVisibleAsync();await option.ClickAsync();}
}
